// Release boot (spec 157 R13, D5, R3), generated by utils/build-release.js: the startup meter, then the bundle;
// ?esm=1 runs the source modules. A bundle that cannot load shows the failure on the startup screen.
import { showStartupFailure } from "./game_startup_meter.entry-62SKHIPB.js";
const esm = new URLSearchParams(location.search).has("esm");
try {
  if (esm) {
    const response = await fetch(new URL("./dev.esm-73DEE072.json", import.meta.url));
    if (!response.ok) throw new Error(`The source graph answered ${response.status}`);
    for (const href of await response.json()) {
      const link = document.createElement("link");
      link.rel = "modulepreload";
      link.href = href;
      document.head.append(link);
    }
  }
  await import(esm ? "../src/entrypoints/dev.entry.js?v=0.50.91" : "./dev.entry-ZNEPFGCE.js");
} catch (error) {
  console.error("[Bootstrap] The game's code could not load.", error);
  showStartupFailure();
}
